CREATE OR ALTER PROCEDURE [dbo].[uspIntegrationChannel_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ChannelStatus NVARCHAR(MAX) = NULL
	, @OwnerUserId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ChannelCode]
			, t.[ChannelName]
			, t.[ProviderCode]
			, t.[EnvironmentCode]
			, t.[ChannelStatus]
			, t.[ConfigJson]
			, t.[SecretReference]
			, t.[OwnerUserId]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[IntegrationChannel] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ChannelCode] LIKE CONCAT('%', @SearchText, '%') OR t.[ChannelName] LIKE CONCAT('%', @SearchText, '%') OR t.[ProviderCode] LIKE CONCAT('%', @SearchText, '%') OR t.[EnvironmentCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@ChannelStatus, '') = '' OR t.[ChannelStatus] = @ChannelStatus)
			AND (@OwnerUserId IS NULL OR t.[OwnerUserId] = @OwnerUserId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'channelCode' THEN r.[ChannelCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'channelCode' THEN r.[ChannelCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'channelName' THEN r.[ChannelName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'channelName' THEN r.[ChannelName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'providerCode' THEN r.[ProviderCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'providerCode' THEN r.[ProviderCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'environmentCode' THEN r.[EnvironmentCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'environmentCode' THEN r.[EnvironmentCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'channelStatus' THEN r.[ChannelStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'channelStatus' THEN r.[ChannelStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'configJson' THEN r.[ConfigJson] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'configJson' THEN r.[ConfigJson] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'secretReference' THEN r.[SecretReference] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'secretReference' THEN r.[SecretReference] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ownerUserId' THEN r.[OwnerUserId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ownerUserId' THEN r.[OwnerUserId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
